    c('PLAN8-forms', 'PLAN 8', 'sub f ($x) { return $x } sub g\n($x)\n{ return $x } say f(1), g(2); sub h($x){return $x} say h(3); sub k() { return 1 }; say k(); sub a3($c) { return 1 if $c; return 2 } say a3(1), a3(0);', out='12\n3\n1\n12\n'),
    c('PLAN8-return-loop', 'PLAN 8', 'sub f() { my $i = 0; while (true) { $i++; return $i if $i > 3; } } say f(); sub g() { my $i = 0; while ($i < 5) { $i++; next if $i < 3; return $i; } return -1 } say g(); sub v() { return 5 } v(); v() if true; say "ok";', out='4\n3\nok\n'),
    c('PLAN8-lines', 'PLAN 8', 'sub f() { return 1 } my $u; say "a";\nmy $r = f()\n  + $u;\nsub g($w) {\n  return 1 + $w;\n}\n$r = g(undef);', out='a\n', err='(?s)in addition \\(\\+\\) at \\S+ line 3\\..*in addition \\(\\+\\) at \\S+ line 6\\.'),
