    c('PLAN8-underscore', 'PLAN 8', 'sub f($_) { return 1 }', compiles=False, err="Can't use global \\$_ in subroutine signature"),
    c('PLAN8-deep', 'PLAN 8', "no warnings 'recursion'; sub d($n) { return $n == 0 ? 0 : 1 + d($n - 1) } say d(1000000);", out='1000000\n'),
    # ---- found by the review of step 8
    c('T143', 'TRAPS; PLAN 8', 'sub g($p = "d") { return "[" . $p . "]" } sub cnt($p = "-", $q = "-", $r = "-") { return $p . "," . $q . "," . $r } sub three() { return ("a") x 3 } sub last2($x) { ($x) x 2 } my $n = 0; say g(("a") x $n); say cnt(("a") x $n, "z"); say cnt(("a") x 2); say cnt(1 ? ("a") x 2 : "b"); say cnt(0 || ("a") x 2); say cnt(three()); say cnt(last2("k")); my $s = three(); say $s; sub d($x = ("a") x 2) { return $x } say d();', out='[d]\nz,-,-\na,a,-\na,a,-\na,a,-\na,a,a\nk,k,-\naaa\naa\n'),
    c('T144', 'TRAPS; PLAN 8', 'my $g = 1; sub bump() { $g = 9; return 5 } sub f($x //= bump(), $y = 0) { return $x . "," . $y } say f(undef, $g); $g = 1; sub h($x ||= bump(), $y = 0) { return $x . "," . $y } say h(0, $g); $g = 1; say f(undef, $g + 0);', out='5,9\n5,9\n5,1\n'),
    c('T145', 'TRAPS; PLAN 8', 'sub a($x, $c) { $x * 2 if $c } sub b($x, $c) { $x++ if $c } sub c($x, $c) { $x = 7 unless $c } sub d($x, $c) { a($x, 1) if $c } say "[" . a(4, 1) . "]"; say "[" . a(4, 0) . "]"; say "[" . a(4, "") . "]"; say "[" . b(4, 0) . "]"; say "[" . c(4, 3) . "]"; say "[" . d(4, 0) . "]"; a(1, 1); a(1, 0);', out='[8]\n[0]\n[]\n[0]\n[3]\n[0]\n'),
    c('T146', 'TRAPS; PLAN 8', 'sub none() { return; } sub show($p) { return defined($p) ? "[" . $p . "]" : "U" } sub cnt($p = "-", $q = "-") { return show($p) . show($q) } say cnt((none())); say cnt(+none()); say cnt((1 and none())); say cnt((0 or none())); say cnt(1 && none()); say cnt(none() || none()); say cnt(1 ? none() : 0); say cnt((none()), "z"); my $v = (none()); say show($v); say cnt((1 xor none())); say cnt(!none());', out='[-][-]\n[-][-]\n[-][-]\n[-][-]\n[-][-]\n[-][-]\n[-][-]\n[z][-]\nU\n[1][-]\n[1][-]\n'),
    c('T136-brackets', 'TRAPS; PLAN 8', 'say((f (1)));\nsub f($x) { return $x + 1 }', compiles=False, err='syntax error at .* near "f \\("'),
