    c('T136-not-first', 'TRAPS; PLAN 8', 'say(+(f (1))); say 1 + f (1); say g(f (1)); my $r = (f (1)); say $r; sub f($x) { return $x + 1 } sub g($x) { return $x }', out='2\n3\n2\n2\n'),
    c('T136-v-underscore', 'TRAPS; PLAN 8', 'say v1_0(); sub v1_0() { return 1 }', compiles=False, err='syntax error at .* near "v1_0\\("'),
    c('T136-v-fine', 'TRAPS; PLAN 8', 'say v_1(), v1a(), vv1(), V1(); sub v_1() { return 1 } sub v1a() { return 2 } sub vv1() { return 3 } sub V1() { return 4 }', out='1234\n'),
    c('T28-for', 'TRAPS; PLAN 8', 'sub for($p) { return $p + 10 }\nmy $r = 1 + for(3);', compiles=False, err='syntax error at .* near "\\+ for"'),
    c('T135-t', 'TRAPS; PLAN 8', 'sub t($p) { return $p + 10 } my $n = -t(2); say defined($n) ? "d[" . $n . "]" : "u";', out='d[]\n'),
    c('T147', 'TRAPS; PLAN 8', 'bump(); my $x += 10; say $x; tag(); my $s .= "a"; say $s; one(); my $d //= 10; say $d; sub bump() { $x++ } sub tag() { $s = "q" } sub one() { $d = 1 }', out='11\nqa\n1\n'),
    c('T148', 'TRAPS; PLAN 8', 'my $n; sub v($x) { $x * 2 } say "a";\nv($n);', out='a\n', err='Use of uninitialized value \\$x in multiplication \\(\\*\\)'),
