    c('PLAN9-push', 'PLAN 9', 'my @a; my $r = push @a, 1, 2; say $r; say pop(@a); say shift(@a); my $u = pop(@a); say defined($u) ? "d" : "u"; $r = unshift @a, 5, 6; say $r, $a[0], $a[1]; my @b = (7, 8); push @a, @b, 9; say scalar(@a); push @a, @a; say scalar(@a);', out='2\n2\n1\nu\n256\n5\n10\n'),
    c('PLAN9-push-none', 'PLAN 9', 'my @a; push @a; say scalar(@a);', out='0\n', err='Useless use of push with no values'),
    c('PLAN9-splice', 'PLAN 9', 'my @a = (0,1,2,3,4,5); my @r = splice(@a, 1, 2); say "@r | @a"; @r = splice(@a, 2); say "@r | @a"; @r = splice(@a, 1, 0, 7, 8); say "@r | @a"; @r = splice(@a, -1); say "@r | @a"; @r = splice(@a, 0, -1); say "@r | @a"; @r = splice(@a); say "@r | @a"; @a = (1,2,3); @r = splice(@a, 3, 1, 9); say "@a"; @r = splice(@a, 1, 10); say "@r | @a";', out='1 2 | 0 3 4 5\n4 5 | 0 3\n | 0 7 8 3\n3 | 0 7 8\n0 7 | 8\n8 | \n1 2 3 9\n2 3 9 | 1\n'),
    c('PLAN9-splice-past', 'PLAN 9', 'my @a = (1,2,3); my @r = splice(@a, 5, 1); say scalar(@a);', out='3\n', err='splice\\(\\) offset past end of array'),
    c('PLAN9-splice-before', 'PLAN 9', 'my @a = (1,2,3); my @r = splice(@a, -9);', err='Modification of non-creatable array value attempted, subscript -9', exit=255),
    c('PLAN9-range', 'PLAN 9', 'my @a = (1..5); say scalar(@a); @a = (3..1); say scalar(@a); @a = (-2..2); say "@a"; @a = (1.9..4.1); say "@a"; my $n = 3; @a = (1..$n); say "@a"; @a = (9223372036854775806..9223372036854775807); say scalar(@a);', out='5\n0\n-2 -1 0 1 2\n1 2 3 4\n1 2 3\n2\n'),
    c('PLAN9-range-far', 'PLAN 9', 'my @a = (1e20..1e20);', err='Range iterator outside integer range', exit=255),
    c('PLAN9-foreach', 'PLAN 9', 'my @a = (1,2,3); for my $x (@a) { print $x; } say ""; foreach my $x (@a, 4, 5..6) { print $x; } say ""; OUT: for my $x (@a) { for my $y (@a) { next OUT if $y > $x; last OUT if $x == 3; print $x, $y, " "; } } say ""; my $x = 5; for my $x (1..$x) { print $x } say $x; my @u = (1); $u[2] = 3; for my $e (@u) { print defined($e) ? $e : "u" } say "";', out='123\n123456\n11 21 22 \n123455\n1u3\n'),
    c('PLAN9-foreach-many', 'PLAN 9', 'my $c = 0; for my $i (1..3000000) { $c++ } say $c;', out='3000000\n'),
    c('PLAN9-flatten', 'PLAN 9', 'sub three($p, $q, $r) { return "$p$q$r" } my @a = (1,2); say three(@a, 3); say three(0, @a); my @e; say three(@e, 1, @a); sub cnt($p = "-", $q = "-") { return "$p$q" } say cnt(@e); say cnt(@a); say cnt((@a)[0]);', out='123\n012\n112\n--\n12\n1-\n'),
    c('PLAN9-flatten-many', 'PLAN 9', 'sub two($p, $q) { return "$p$q" } my @a = (1,2,3); say "x"; say two(@a);', out='x\n', err="Too many arguments for subroutine 'main::two' \\(got 3; expected 2\\)", exit=255),
    c('PLAN9-nothing', 'PLAN 9', 'sub f() { return 5 } sub none() { return } my @a = f(); say scalar(@a); my @c = none(); say scalar(@c); my @d = (1, none(), 2); say scalar(@d); my ($y, $z) = (none(), 7); say $y;', out='1\n0\n2\n7\n'),
    c('PLAN9-slice', 'PLAN 9', 'my @a = (10,20,30,40); my @s = @a[1,2]; say "@s"; @s = @a[1..3]; say "@s"; @s = @a[-1,0]; say "@s"; @s = @a[5,1]; say defined($s[0]) ? "d" : "u", $s[1]; my @i = (0,2); @s = @a[@i]; say "@s"; my ($x, $y) = @a[2,3]; say "$x$y"; say((10,20,30)[1]); my @t = (10,20,30)[0,2]; say "@t"; my @e = (@a)[9,10]; say scalar(@e); @e = ()[0,1]; say scalar(@e);', out='20 30\n20 30 40\n40 10\nu20\n10 30\n3040\n20\n10 30\n2\n0\n'),
    c('PLAN9-slice-left', 'PLAN 9', 'my @a = (1,2,3); @a[0,1] = (8,9); say "@a"; $#a = 0; say scalar(@a);', out='8 9 3\n1\n'),
    c('PLAN9-repeat', 'PLAN 9', 'my @a = (0) x 3; say "@a"; @a = (1,2) x 2; say "@a"; my @b = (@a) x 2; say scalar(@b); @a = ("a") x 0; say scalar(@a); @a = "ab" x 2; say "@a";', out='0 0 0\n1 2 1 2\n8\n0\nabab\n'),
    c('PLAN9-names', 'PLAN 9', 'my @a = (1,2); my @b = (3); say $a[0] + $b[0]; my $x = 9; my @x = (1,2,3); say $x; say $x[0]; say scalar(@x);', out='4\n9\n1\n3\n'),
    c('PLAN9-element-ops', 'PLAN 9', 'my @a = (1,2,3); $a[0]++; ++$a[1]; $a[2] += 10; $a[0] .= "x"; $a[5] //= 7; $a[4]++; say $a[0], $a[1], $a[2], $a[4], $a[5]; my @u; $u[2] .= "s"; $u[1] += 5; $u[0]++; say "@u"; my $i = 0; $a[$i++] = $i; say $a[0]; $a[$i] = $i++; say $a[2], $i; my @t = (10,20,30); $i = 0; say $t[$i++] + $t[$i++];', out='2x31317\n1 5 s\n1\n12\n30\n'),
    c('PLAN9-undef', 'PLAN 9', 'my @a = (1); @a = undef; say scalar(@a); my @b = (undef, undef); say scalar(@b); @a = (); say scalar(@a);', out='1\n2\n0\n'),
    c('PLAN9-scalar', 'PLAN 9', 'my @a = (1,2,3); say scalar(@a); say scalar(@a) + 1; say scalar(1 + 1);', out='3\n4\n2\n'),
    c('PLAN9-later', 'PLAN 9', 'my @a = (1,2,3); say exists $a[1] ? "y" : "n"; delete $a[2]; say scalar(@a); my @r = (1,2); for my ($i, $j) (@a, 4, 5) { print "$i$j " } say "";', out='y\n2\n12 45 \n'),
    # ---- found by the review of step 9
    c('T157', 'TRAPS; PLAN 9', 'my $x = 1; sub bump() { $x = 9; return 5 } my @b = ($x, bump()); say "@b"; $x = 1; say $x, bump(); $x = 1; my ($p, $q) = ($x, bump()); say "$p $q"; my $i = 1; @b = ($i, $i++); say "@b"; @b = ($i, $i = 7); say "@b"; $x = 1; @b = (($x) x 2, bump()); say "@b"; $x = 1; @b = ((1 ? $x : 0), bump()); say "@b";', out='9 5\n95\n9 5\n2 1\n7 7\n9 9 5\n9 5\n'),
    c('T157-array', 'TRAPS; PLAN 9', 'my @a = (1, 2, 3); sub chg() { $a[0] = 50; return 5 } my @b = (@a, chg()); say "@b"; @a = (1, 2, 3); say @a, chg(); @a = (1, 2, 3); @b = (@a[0, 1], chg()); say "@b"; @a = (1, 2, 3); @b = ($a[0], chg()); say "@b"; @a = (1, 2, 3); for my $x (@a, chg()) { print $x, " "; } say "";', out='50 2 3 5\n50235\n50 2 5\n50 5\n50 2 3 5 \n'),
    c('T158', 'TRAPS; PLAN 9', 'my @a = (1, 2, 3); my $i = 0; $a[$i] = ($i = 2); say "@a"; @a = (1, 2, 3); sub bump() { $a[0] = 99; return 1 } $a[bump()] = $a[0]; say "@a"; @a = (1, 2, 3); $i = 0; ($i, $a[$i]) = (1, 5); say "@a $i";', out='1 2 2\n99 99 3\n5 2 3 1\n'),
    c('T159', 'TRAPS; PLAN 9', 'my @a = (1, 2, 3); my $i = 0; $a[$i] += ($i = 2); say "@a"; @a = (1, 2, 3); $a[0] += shift(@a); say "@a"; @a = (1, 2, 3); $a[$#a] += pop(@a); say "@a"; my @e; $e[5] //= push(@e, 1); say scalar(@e), $e[5];', out='3 2 3\n2 3\n1 2\n77\n'),
    c('T160', 'TRAPS; PLAN 9', 'my @a; $a[5] &&= 1; say scalar(@a);', out='6\n'),
    c('T160-before', 'TRAPS; PLAN 9', 'my @e; say "a"; $e[-1] &&= 5; say "after";', out='a\n', err='Modification of non-creatable array value attempted, subscript -1', exit=255),
    c('T160-order', 'TRAPS; PLAN 9', 'my @a = (1); sub p($v) { say $v; return $v } $a[-9] += p(5);', out='', err='Modification of non-creatable array value attempted, subscript -9', exit=255),
    c('T161', 'TRAPS; PLAN 9', 'sub f($x = 0, $y = 0) { return 1 } my @a; for my $x ($a[5]) { say scalar(@a); } my @b; for my $x (@b[5, 6]) { } say scalar(@b); my @c; f($c[5]); say scalar(@c); f(@c[5, 6]); say scalar(@c); my @d; my $r = $d[5] // 0; my @t = @d[5, 6]; say scalar(@d), " ", scalar(@t);', out='6\n7\n0\n7\n0 2\n'),
    c('T161-before', 'TRAPS; PLAN 9', 'my @a; for my $x ($a[-5]) { say "in"; } say "after";', out='', err='Modification of non-creatable array value attempted, subscript -5', exit=255),
    c('T162', 'TRAPS; PLAN 9', 'my @a = (1,2,3); my @b = (4); for my $x ((@a) x 2) { $a[0] = 9; print $x; } say ""; @a = (1,2,3); for my $x ((@a)[0, 1]) { $a[0] = 9; print $x; } say ""; @a = (1,2,3); for my $x (@a && @b) { $b[0] = 9; print $x; } say ""; @a = (1,2,3); for my $x ($#a) { push @a, 7; print $x; } say ""; my $s = "abc"; for my $x (substr($s, 0, 1)) { $s = "zzz"; print $x; } say "";', out='923923\n92\n9\n3\nz\n'),
    c('T162-or', 'TRAPS; PLAN 9', 'my @a = (1,2,3); my @b = (4); for my $x (@a || @b) { print $x, " "; } say "";', out='3 \n'),
    c('T163', 'TRAPS; PLAN 9', 'sub p($v) { print "<", $v, ">"; return $v } say((p(10), p(20))[p(1)]); my $i = 0; say(($i, 5)[$i++]); my @a = (1, 2, 3); sub sh() { shift(@a); return 0 } say((@a)[sh()]);', out='<1><10><20>20\n1\n2\n'),
    c('T164', 'TRAPS; PLAN 9', 'my @e; my @b = (@e)[0, 1]; say scalar(@b); @b = (@e)[0]; say scalar(@b); @b = (1, 2, 3)[5, 6]; say scalar(@b); @b = (1, 2, 3)[5]; say scalar(@b); sub f($x = "d", $y = "d") { return $x . $y } say f((@e)[0]); my $v = (@e)[0]; say defined($v) ? 1 : 0;', out='0\n0\n2\n1\ndd\n0\n'),
    c('T165', 'TRAPS; PLAN 9', 'my @a = (1,2,3,4,5); my @r = splice(@a, 0, 1e30); say scalar(@r), " ", scalar(@a); @a = (1,2,3,4,5); @r = splice(@a, 1e30); say scalar(@r), " ", scalar(@a);', out='4 1\n1 4\n'),
    c('T166', 'TRAPS; PLAN 9', 'my $lo = -9223372036854775807 - 1; my @r = ($lo .. $lo + 1); say scalar(@r); for my $i (0, $lo .. $lo + 1) { print "."; } say ""; for my $i ($lo .. $lo + 1) { print "."; } say "not reached";', out='2\n...\n', err='Range iterator outside integer range', exit=255),
    c('T166-edge', 'TRAPS; PLAN 9', 'my $n = 0; for my $i (-9223372036854775295 .. -9223372036854775294) { $n++; } say $n; for my $i (3 .. -9223372036854775295) { $n++; } say $n; for my $i (3 .. -9223372036854775296) { $n++; } say "not reached";', out='2\n2\n', err='Range iterator outside integer range', exit=255),
    c('T169', 'TRAPS; PLAN 9', 'my @a = (1); for my $x (1 ? $a[5] : 0) { } print scalar(@a); my @b = (1); for my $x (0 || $b[5], 1 && $b[7]) { } print " ", scalar(@b); my @c = (1); for my $x (($c[5]) x 2, +$c[6]) { } print " ", scalar(@c); my @d = (1); for my $x ($d[5] || 0, $d[5] // 1, $d[5] ? 1 : 2, ($d[5], 1)[0]) { } say " ", scalar(@d);', out='6 8 7 1\n'),
    c('T170', 'TRAPS; PLAN 9', 'my @a = (1, 2); for my $x (@a) { my $x = 5; print $x; } say "";', out='55\n'),
    c('T171', 'TRAPS; PLAN 9', 'my $x = 7; for $x (1, 2) { print $x; } say $x; foreach (my $k = 0; $k < 2; $k++) { print $k; } say "";', out='127\n01\n'),
    c('T172', 'TRAPS; PLAN 9', 'my $n = 3; for my $i (1 .. $n) { $n = 1; print $i; } say "";', out='123\n'),
    c('T166-high', 'TRAPS; PLAN 9', 'my $n = 0; for my $i (9223372036854775805 .. 9223372036854775807) { $n++; } say $n;', out='3\n'),
    # ---- step 10, proposing it
    c('T173', 'TRAPS; PLAN 10', 'for my $r (2147483647, 2147483648, 4294967296, 4294967297, -2147483648, -2147483649, 1.9, -1.9, -0.5) { my @s = sort { $r } (1, 2); print "$r:@s  "; } say "";', out='2147483647:2 1  2147483648:1 2  4294967296:1 2  4294967297:2 1  -2147483648:1 2  -2147483649:2 1  1.9:2 1  -1.9:1 2  -0.5:1 2  \n'),
    c('T173-log', 'TRAPS; PLAN 10', 'my @log; my @s = sort { push @log, "$a$b"; $a <=> $b } (5,3,8,1,9,2,7); say "@log"; @log = (); @s = sort { push @log, "$a$b"; $b <=> $a } (5,3,8,1,9,2,7); say "@log"; @log = (); @s = reverse sort { push @log, "$a$b"; $a <=> $b } (5,3,8,1,9,2,7); say "@log | @s";', out='53 81 92 31 38 58 27 79 12 23 37 75 78 89\n53 81 92 58 51 31 97 72 89 87 57 52 32 21\n53 81 92 31 38 58 27 79 12 23 37 75 78 89 | 9 8 7 5 3 2 1\n'),
    c('T173-runs', 'TRAPS; PLAN 10', 'my @log; my @s = sort { push @log, "$a$b"; $a <=> $b } (1,2,3,4,5,6,7); say "@log"; @log = (); @s = sort { push @log, "$a$b"; $a <=> $b } (7,6,5,4,3,2,1); say "@log";', out='12 34 56 13 32 57 76 15 52 53 54\n76 54 32 64 65 21 41 42 43\n'),
    c('T173-loose', 'TRAPS; PLAN 10', 'my @s = sort { 1 } (1,2,3,4,5); say "@s"; @s = sort { -1 } (1,2,3,4,5); say "@s"; @s = sort { $a <=> $b } (9007199254740993, 9007199254740992.0, 9007199254740992); say "@s";', out='5 4 3 2 1\n1 5 3 2 4\n9007199254740992 9007199254740993 9.00719925474099e+15\n'),
    c('T173-stable', 'TRAPS; PLAN 10', 'my @s = reverse sort { lc($a) cmp lc($b) } ("b", "A", "a", "B"); say "@s"; @s = sort { lc($b) cmp lc($a) } ("b", "A", "a", "B"); say "@s"; @s = sort (10, 9, 2.5, "3", true, 1e1, "a", "B"); say "@s";', out='B b a A\nb B A a\n1 10 10 2.5 3 9 B a\n'),
    c('T174', 'TRAPS; PLAN 10', 'sub f() { my @s = sort { return 5 } (3,1,2); return "@s"; } say f(); sub g() { my @s = map { return 5 } (3,1,2); return "@s"; } say g(); my @t = sort { return $a <=> $b } (3,1,2); say "@t";', out='2 1 3\n5\n1 2 3\n'),
    c('T175', 'TRAPS; PLAN 10', 'my @s = map { "a", $_ } (1,2);', compiles=False, err='syntax error'),
    c('T175-number', 'TRAPS; PLAN 10', 'my @s = map { 1, $_ } (1,2);', compiles=False, err='syntax error'),
    c('T175-empty', 'TRAPS; PLAN 10', 'my @s = map { } (1,2);', compiles=False, err='syntax error'),
    c('T175-grep', 'TRAPS; PLAN 10', 'my @s = grep { 1, 0 } (1,2);', compiles=False, err='syntax error'),
    c('T175-sort', 'TRAPS; PLAN 10', 'my @s = sort { 1, 0 } (1,2);', compiles=False, err='syntax error'),
    c('T175-blocks', 'TRAPS; PLAN 10', 'my @s = map { 1.5, $_ } (1,2); print scalar(@s); @s = map { -1, $_ } (1,2); print scalar(@s); @s = map { true, $_ } (1,2); print scalar(@s); @s = map { lc("A"), $_ } (1,2); print scalar(@s); @s = map { $_, 1 } (1,2); print scalar(@s); @s = map { ; 1, $_ } (1,2); print scalar(@s); @s = map {; } (1,2); say scalar(@s);', out='4444440\n'),
    c('T176', 'TRAPS; PLAN 10', 'my @s = map { if ($_ > 1) { $_ } } (1,2,3); say scalar(@s), ":", join(",", @s);', out='3:,2,3\n'),
    c('T176-grep', 'TRAPS; PLAN 10', 'my @s = grep { ($_, 0) } (1,2,3); say scalar(@s);', out='0\n', err='Useless use of a variable in void context'),
    c('T177', 'TRAPS; PLAN 10', 'my @a = (1); my @r = map { $_ } $a[5]; print scalar(@a); @r = grep { 1 } $a[7]; print " ", scalar(@a); @r = map { $_ } @a[9, 10]; say " ", scalar(@a);', out='6 8 11\n'),
    c('T177-not', 'TRAPS; PLAN 10', 'my @a = (1); my $j = join(",", $a[9] // 0); my @r = reverse($a[12] // 0, 1); say scalar(@a);', out='1\n'),
    c('T177-sort', 'TRAPS; PLAN 10', 'my @a = (1); my @r = sort { $a <=> $b } $a[9], 1; say scalar(@a);', out='1\n', err='Use of uninitialized value in sort'),
    c('T178', 'TRAPS; PLAN 10', 'my @a = (1,2,3); my $n = grep { $_ > 1 } @a; my $m = map { ($_, $_) } @a; say "$n $m"; say "has" if grep { $_ == 2 } @a; say "n" . grep { $_ } @a; say 1 + map { $_ } @a;', out='2 6\nhas\nn3\n4\n'),
    c('T178-reverse', 'TRAPS; PLAN 10', 'my $r = reverse("abc", "def"); say $r; say reverse("abc", "def"); say scalar(reverse("abc"));', out='fedcba\ndefabc\ncba\n'),
    c('T178-sort', 'TRAPS; PLAN 10', 'my @a = (3,1,2); my $s = sort { $a <=> $b } @a; say defined($s) ? $s : "undef";', out='undef\n', err='Useless use of sort in scalar context'),
    c('T179', 'TRAPS; PLAN 10', 'my @a = (3,1,2); my @log; @a = sort { push @log, "$a[0]$a[1]$a[2]"; $a <=> $b } @a; say "@log | @a";', out='312 312 312 | 1 2 3\n'),
    c('T179-store', 'TRAPS; PLAN 10', 'my @a = (3,1,2); my @b = sort { $a[0] = 0; $a <=> $b } @a; say "@a | @b"; my @c = (3,1,2); my @d = sort { $a++; 0 } @c; say "@c";', out='0 1 2 | 0 1 2\n5 1 3\n'),
    c('T179-push', 'TRAPS; PLAN 10', 'my @a = (3,1,2); @a = sort { push @a, 1; $a <=> $b } @a; say "@a"; my @c = (3,1,2); my @d = sort { push @c, 1; $a <=> $b } @c; say "@c | @d";', out='1 2 3\n3 1 2 1 1 1 | 1 2 3\n'),
    c('T180', 'TRAPS; PLAN 10', 'sub show() { return $_ * 2 } my @s = map { show() } (1,2); say "@s"; sub cmpf() { return $a <=> $b } @s = sort { cmpf() } (3,1,2); say "@s";', out='2 4\n1 2 3\n'),
    c('T180-nest', 'TRAPS; PLAN 10', 'for (1,2) { print $_; for (7,8) { print $_; } print $_; } say ""; my @s = map { my $o = $_; map { $o . $_ } (1,2) } ("a","b"); say "@s"; @s = sort { my @t = sort { $b <=> $a } ($a, $b); $t[0] <=> $a } (3,1,2); say "@s";', out='17812782\na1 a2 b1 b2\n3 1 2\n'),
    c('T180-alias', 'TRAPS; PLAN 10', 'my @a = (1,2); for (@a) { $_ *= 2 } say "@a"; my @r = map { $_ *= 2 } @a; say "@a"; @r = grep { $_++ } @a; say "@a"; my $p = 1; my $q = 2; @r = map { $p = 7; $_ } ($p, $q); say "@r";', out='2 4\n4 8\n5 9\n7 2\n'),
    c('T180-default', 'TRAPS; PLAN 10', 'my @s = map { length } ("ab", "c"); say "@s"; @s = grep { defined } (1, undef); say scalar(@s); say for 1, 2;', out='2 1\n1\n1\n2\n'),
    c('T180-expr', 'TRAPS; PLAN 10', 'my @s = map lc, ("A", "B"); say "@s"; @s = grep $_ > 1, (1,2,3); say "@s"; @s = map +($_ * 2), (1,2); say "@s"; @s = (9, map { $_ * 2 } 1, 2, 9); say "@s";', out='a b\n2 3\n2 4\n9 2 4 18\n'),
    c('T180-expr-brackets', 'TRAPS; PLAN 10', 'my @s = map ($_ * 2), (1,2); say scalar(@s);', out='0\n', err='Useless use of a constant'),
    c('T181', 'TRAPS; PLAN 10', 'my @a = (1,2,3); my @r = map { push @a, 9 if @a < 6; $_ } @a; say "@r | @a"; for (@a) { push @a, 8 if @a < 8; print $_; } say "";', out='1 2 3 | 1 2 3 9 9 9\n12399988\n'),
    c('T182', 'TRAPS; PLAN 10', 'sub f(@rest, $x) { 1 }', compiles=False, err='Slurpy parameter not last'),
    c('T182-default', 'TRAPS; PLAN 10', 'sub g(@r = (1,2)) { 1 }', compiles=False, err='A slurpy parameter may not have a default value'),
    c('T182-copies', 'TRAPS; PLAN 10', 'sub f($x, @rest) { return scalar(@rest) . ":$x" } say f(1), " ", f(1, 2, 3); my @a = (5, 6); say f(@a, @a); sub g(@all) { $all[0] = 9; return "@all" } say g(@a); say "@a"; sub h($x, $y = 5, @rest) { return "$x $y @rest" } say h(1); say h(1, 2, 3, 4); sub k($x, @) { return $x } say k(1, 2, 3);', out='0:1 2:1\n3:5\n9 6\n5 6\n1 5 \n1 2 3 4\n1\n'),
    c('T182-join', 'TRAPS; PLAN 10', 'my @a = ("x", "y"); say join(@a, 1, 2); say join(",", 1, 2, 3); say join ",", (1, 2), 3; say join("-", @a) . "!"; say join(",", "a"); say join(",", 1.5, true, false, 1e20, 10/3);', out='122\n1,2,3\n1,2,3\nx-y!\na\n1.5,1,,1e+20,3.33333333333333\n'),
    c('T182-join-undef', 'TRAPS; PLAN 10', 'say join(",", 1, undef, 2);', out='1,,2\n', err='Use of uninitialized value in join or string'),
    c('T183', 'TRAPS; PLAN 10', 'sub f() { return (4, 5, 6) } my $x = f(); my ($y) = f(); my @z = f(); say "$x $y @z"; say scalar(f()); say f() + 1; say "n" . f();', out='6 4 4 5 6\n6\n7\nn6\n'),
    c('T183-shapes', 'TRAPS; PLAN 10', 'sub f() { my @a = (1,2,3); return reverse @a } my $x = f(); say $x; sub g() { return map { $_ } (4,5) } my $y = g(); say $y; sub h() { my @a = (7, 8); return splice(@a, 0, 2) } my $z = h(); say $z; sub sl() { my @a = (4, 5); return @a[0, 1] } my $w = sl(); say $w;', out='321\n2\n8\n5\n'),
    c('T183-sort', 'TRAPS; PLAN 10', 'sub f() { my @a = (3,1,2); return sort { $a <=> $b } @a } my $x = f(); say defined($x) ? $x : "undef";', out='undef\n'),
    c('T183-range', 'TRAPS; PLAN 10', 'sub f() { return 1 .. 3 } my @z = f(); say "@z"; my $x = f(); say defined($x) ? "d[$x]" : "u";', out='1 2 3\nd[]\n', err='Use of uninitialized value .* in range'),
    c('T183-empty', 'TRAPS; PLAN 10', 'sub f() { return () } my $x = f(); say defined($x) ? 1 : 0; my @z = f(); say scalar(@z); sub g() { return (7) } my $y = g(); say $y; sub n() { return } sub two() { return (n(), n()) } my @b = two(); say scalar(@b);', out='0\n0\n7\n0\n'),
    c('T183-arms', 'TRAPS; PLAN 10', 'sub f($c) { my @a = (7,8,9); return $c ? @a : 0 } say scalar(f(1)), scalar(f(0)); sub g($c) { my @a = (7,8); return $c || @a } say scalar(g(0)), scalar(g(5));', out='30\n25\n'),
    c('T183-last', 'TRAPS; PLAN 10', 'sub f() { my @a = (7,8,9); @a } my $x = f(); say $x; sub g() { (4,5,6) } my $y = g(); say $y;', out='3\n6\n'),
    c('T183-context', 'TRAPS; PLAN 10', 'sub c($w) { print $w, "=", wantarray ? "list" : defined(wantarray) ? "scalar" : "void", " "; return 1 } my @l = map { c("in"); c("last") } (1); my @g = grep { c("g") } (1); my @s = sort { c("s") } (1,2); my $j = join(c("sep"), c("item")); my @r = reverse(c("rev")); for (c("for")) { c("body") } c("stmt") for c("post"); sub p() { return map { c("ret") } (1) } my $sc = p(); say "";', out='in=void last=list g=scalar s=scalar sep=scalar item=list rev=list for=list body=void post=list stmt=void ret=list \n'),
    c('T183-uses', 'TRAPS; PLAN 10', 'sub f() { return (1, 2) } my @a = (f())[1]; say "@a"; my ($p, $q) = f(); say $p + $q; for my $x (f()) { print $x } say ""; say f(); sub r(@v) { return @v } my @b = r(f(), r(f())); say "@b";', out='2\n3\n12\n12\n1 2 1 2\n'),
    c('T184', 'TRAPS; PLAN 10', 'my $n = 0; $n += $_ for 1, 2, 3; say $n; my @b; push @b, $_ * 2 for (1,2), 3; say "@b"; my $i = 0; print $i++ for (1,2) x 2; say ""; print "$_ " for 1 .. 3; say "";', out='6\n2 4 6\n0123\n1 2 3 \n'),
    c('T184-global', 'TRAPS; PLAN 10', '$_ = 5; for (1) { } print $_; my @s = map { $_ } (1); say $_;', out='55\n'),
    # ---- step 10, by its review
    c('T185', 'TRAPS; PLAN 10', 'my @a = (1, 2, 3); sub chg() { $a[0] = 50; return 7 } my @r = (reverse(@a), chg()); say "@r"; @a = (1, 2, 3); @r = ((grep { 1 } @a), chg()); say "@r"; @a = (1, 2, 3); @r = ((sort { $a <=> $b } @a), chg()); say "@r"; @a = (1, 2, 3); @r = ((map { $_ } @a), chg()); say "@r"; @a = (1, 2, 3); say join("-", reverse(@a), chg());', out='3 2 50 7\n50 2 3 7\n50 2 3 7\n1 2 3 7\n3-2-50-7\n'),
    c('T185-scalar', 'TRAPS; PLAN 10', 'my $v = 5; sub bump() { $v = 9; return 5 } my @r = ((grep { 1 } $v), bump()); say "@r"; $v = 5; say((reverse($v, 0))[0] + bump());', out='9 5\n5\n'),
    c('T186', 'TRAPS; PLAN 10', 'my $sep = "-"; sub chs() { $sep = "+"; return 1 } say join($sep, chs(), 2, 3);', out='1+2+3\n'),
    c('T187', 'TRAPS; PLAN 10', 'my @d = (3); $d[3] = 1; @d = sort { ($a // 0) <=> ($b // 0) } @d; say scalar(@d); my @e = (3, undef, undef, 1); @e = sort { ($a // 0) <=> ($b // 0) } @e; say scalar(@e); my @f = (3); $f[3] = 1; my @c = sort { ($a // 0) <=> ($b // 0) } @f; say scalar(@c); my @g = (3); $g[3] = 1; @g = reverse sort { ($a // 0) <=> ($b // 0) } @g; say scalar(@g);', out='2\n4\n4\n4\n'),
    c('T188', 'TRAPS; PLAN 10', 'my @a = (1); my @r = sort { ($a // 0) <=> ($b // 0) } @a[0 .. 3]; print scalar(@a); my @b = (1); @r = sort { 0 } $b[5]; print " ", scalar(@b); my @c = (1); @r = sort { 1; ($a // 0) <=> ($b // 0) } $c[5], 1; say " ", scalar(@c);', out='4 6 6\n'),
    c('T189', 'TRAPS; PLAN 10', 'my @r = sort true, false; say join("|", @r); @r = sort false, 3, 2; say join("|", @r); @r = sort +true, false; say join("|", @r);', out='|true\n2|3|false\n|1\n'),
    c('T189-call', 'TRAPS; PLAN 10', 'sub k() { return 5 } my @r = sort k(), 3, 1; say "@r"; @r = sort(k(), 3, 1); say "@r"; @r = sort +k(), 3, 1; say "@r";', out='1 3\n1 3 5\n1 3 5\n'),
    c('T190', 'TRAPS; PLAN 10', 'my @z = ("abc"); my @r = sort { $a <=> $b } @z; say scalar(@r);', out='1\n', err="isn't numeric in sort"),
    c('T190-undef', 'TRAPS; PLAN 10', 'my @u = (undef); my @r = sort @u; say scalar(@r);', out='1\n', err='Use of uninitialized value .* in sort'),
    c('T190-block', 'TRAPS; PLAN 10', 'my @z = ("abc", undef); my @r = sort { 1; 0 } @z[0, 0]; my @q = sort { 0 } $z[1]; say scalar(@r) + scalar(@q);', out='3\n'),
    c('T190-brackets', 'TRAPS; PLAN 10', 'my @a = (3, 1, 2); my @r = (sort (@a), 9); say "@r";', out='1 2 3 9\n', err='interpreted as function'),
    c('T190-join', 'TRAPS; PLAN 10', 'say join(undef, "a");', out='a\n', err='Use of uninitialized value in join or string'),
    c('T191', 'TRAPS; PLAN 10', 'for my $i (1 .. 3) { last for 1, 2; print $i; } say ""; sub f() { return $_ for 4, 5; return 0 } say f();', out='123\n4\n'),
    c('T191-slurpy', 'TRAPS; PLAN 10', 'my $v = 5; sub bump() { $v = 9; return 5 } sub f($x, @rest) { return "$x|@rest" } say f(1, $v, bump()); $v = 5; sub g($x, $y //= bump(), @rest) { return "$x|$y|@rest" } say g(1, undef, $v);', out='1|9 5\n1|5|9\n'),
    c('T191-outer', 'TRAPS; PLAN 10', 'for (1, 2) { my @r = map { $_ * 10 } ($_, 5); print "@r;"; } say ""; my @s = map { my @t = sort { $a <=> $b } ($_, 1); $t[0] } (0, 3); say "@s";', out='10 50;20 50;\n0 1\n'),
    c('T192', 'TRAPS; PLAN 10', 'my @s = map { { 5 } } 1; say scalar(@s);', out='1\n', err='Odd number of elements in anonymous hash'),
    c('T192-for', 'TRAPS; PLAN 10', 'for () { say 1; }', compiles=False, err='syntax error'),
    c('T192-two', 'TRAPS; PLAN 10', 'my $n = 0; $n += $_ for 1 .. 3 if 1;', compiles=False, err='syntax error'),
    c('T192-handle', 'TRAPS; PLAN 10', 'my @r = map { say $_ -1 } (5);', out='', err='as a symbol ref', exit=255),
    c('T193', 'TRAPS; PLAN 10', 'sub f() { return 1, 2; } say f(); sub g(@r,) { return scalar(@r); } say g(5); my @b = reverse; say scalar(@b); my @a = (1, 2); sub h(@v) { my @v = (1); return 1; }', out='12\n1\n0\n', err='masks earlier declaration in same scope'),
    c('T193-wrong', 'TRAPS; PLAN 10', 'sub two() { return (1, 0); } my $x = (5, 6, 7)[two()]; say $x; my @a = (1, 2); for my $x (reverse @a) { push @a, 1; last; } say scalar(@a);', out='5\n3\n'),
    c('T194', 'TRAPS; PLAN 10', 'my @a = (1, 2, 3); my @r = map { shift(@a); $_ + 0 } @a; say scalar(@r), scalar(@a); my @b = (1, 2); my @s = (map { $_ + 1 } @b, 5); say "@s"; my @t = map { say $_ } (7); say "@t";', out='30\n2 3 6\n7\n1\n'),
    c('T194-crash', 'TRAPS; PLAN 10', 'my @a = (1, 2, 3); my @r = grep { shift(@a); $_ + 0 } @a; say scalar(@r);', out='', exit=-11),
    c('T194-declare', 'TRAPS; PLAN 10', 'my $_ = 5;', compiles=False, err='Can.t use global \\$_ in "my"'),
    c('T194-signature', 'TRAPS; PLAN 10', 'sub f($_) { return 1 }', compiles=False, err='Can.t use global \\$_ in subroutine signature'),
    c('T195', 'TRAPS; PLAN 10', 'my $x = 3; my $y = 1; my @r = sort +$x, $y; say "@r"; my @a = (3, 1, 2); @r = sort(@a); say "@r"; @r = sort { $a[0] <=> $a[1] } 5, 4; say "@r"; my $n = 0; @r = sort { $n++; $a <=> $b } 1 .. 20; say $n; my @one = sort { say "run"; 0 } 7; say scalar(@one);', out='1 3\n1 2 3\n4 5\n19\n1\n'),
    c('T192-loop', 'TRAPS; PLAN 10', 'my @r = map { my $t = 0; for my $i (1, 2, 3) { next if $i == 2; last if $i == 3; $t += $i; } $t + $_ } (10, 20); say "@r"; my @w = sort { $a <=> $b or $a cmp $b } (2, 1); say "@w"; say scalar(@{[ map({ $_ * 2 } 1, 2) ]});', out='11 21\n1 2\n2\n'),
    c('T167', 'TRAPS; PLAN 9', 'my @a = (1,2,3); my $j = 1; my @s = @a[0]; @s = @a[$j];', out='', err='(?s)Scalar value @a\\[0\\] better written as \\$a\\[0\\].*Scalar value @a\\[\\.\\.\\.\\] better written'),
    c('T167-quiet', 'TRAPS; PLAN 9', 'my @a = (1,2,3); my @b = (1); my $j = 1; my @s = @a[0,]; @s = @a[(0)]; @s = @a[@b]; @s = @a[0 .. 0]; @s = (@a)[0]; say scalar(@s);', out='1\n'),
    c('T168', 'TRAPS; PLAN 9', 'my @a = 1, 2, 3; say scalar(@a);', out='1\n', err='Useless use of a constant \\(2\\) in void context'),
    c('T168-defined', 'TRAPS; PLAN 9', 'my @a = (1);\nsay defined(@a) ? 1 : 0;', compiles=False, err="Can't use 'defined\\(@array\\)'"),
    c('T168-bracket', 'TRAPS; PLAN 9', 'my @a = (1, 2);\nsay(1, 2)[1];', compiles=False, err='syntax error at .* near "\\)\\["'),
    c('T168-last', 'TRAPS; PLAN 9', 'my @g; my ($p, $q); sub f1() { @g = (7, 8, 9) } sub f3() { ($p, $q) = (4, 5, 6) } my $n = f1(); say $n; my @l = f3(); say scalar(@l); $n = f3(); say $n;', out='3\n2\n3\n'),
    c('T168-repeat', 'TRAPS; PLAN 9', 'my @b = (1, 2) x 2 x 2; say scalar(@b), $b[0]; @b = ((1, 2) x 2) x 2; say scalar(@b);', out='12222\n8\n'),
    c('T31-nested', 'TRAPS; PLAN 8', 'sub outer($x) { sub innr() { return $x } return innr() } say outer(1); say outer(2);', out='1\n1\n', err='Variable "\\$x" will not stay shared'),
    c('T31-block', 'TRAPS; PLAN 8', '{ sub inner() { return 1 } } say inner(); if (true) { sub in2() { return 2 } } say in2();', out='1\n2\n'),
    c('T60-label', 'TRAPS; PLAN 8', 'sub f() { last OUT; } my $i = 0; OUT: while ($i++ < 3) { f(); say $i }', out='', err='Exiting subroutine via last'),
    # ---- step 11a, interpolation: found proposing it
    c('T196', 'TRAPS; PLAN 11a', r'''my $x = 3; say "$x-" . ($x = 5); $x = 3; say "$x" . "a" . ($x = 5); $x = 3; say "a$x" . ($x = 5); $x = 3; say $x . "a" . ($x = 5); $x = 1; say "a$x" . $x . ($x = 5);''', out='3-5\n3a5\na35\n5a5\na155\n'),
    c('T196-value', 'TRAPS; PLAN 11a', r'''my $x = 3; say "$x" + ($x = 5); $x = 3; sub ch() { $x = 5; return "c" } say "$x-" . ch(); $x = 3; my @l = ("$x", ch()); say @l; $x = 3; sub two($p, $q) { return "$p$q" } say two("$x", $x = 5);''', out='8\n3-c\n3c\n35\n'),
    c('T197', 'TRAPS; PLAN 11a', r'''my @a = (1, 2); my $i = 0; say "$i $a[$i++] $i"; $i = 0; say "$i$a[$i = 1]";''', out='1 1 1\n12\n'),
    c('T198', 'TRAPS; PLAN 11a', r'''my $t = "t"; my $u = "u"; my $x = "a"; my $z = "z"; my @a = (1, 2); $t .= ($u = "$x$z"); say "$t $u"; $t = "t"; $t .= ($u = "a$x"); say "$t $u"; $t = "t"; $t .= +($u = "@a-"); say "$t $u"; $t = "t"; $t .= ($u = "$a[0]$a[1]"); say "$t $u";''', out='taz u\ntaa u\nt1 2- u\nt12 u\n'),
    c('T198-kept', 'TRAPS; PLAN 11a', r'''my $t = "t"; my $u = "u"; my $x = "a"; my $z = "z"; my @a = (1, 2); $t .= ($u = "$x"); say "$t $u"; $t = "t"; $t .= ($u = "@a"); say "$t $u"; $t = "t"; $t .= ($u = "$a[0]"); say "$t $u"; $t = "t"; $t .= (my $w = "$x$z"); say "$t $w"; $t = "t"; $t .= ($u = "$x$z") . "b"; say "$t $u"; $t = ($u = "$x$z"); say "$t $u"; $x = "$x$x"; say $x; $x .= "$x-$x"; say $x;''', out='ta a\nt1 2 1 2\nt1 1\ntaz az\ntazb az\naz az\naa\naaaa-aa\n'),
    c('T199', 'TRAPS; PLAN 11a', r'''my $x = 3; say "$x::y|"; say "$x::|"; my @a = (1, 2); say "$#a::|";''', out='|\n|\n-1|\n', err='Use of uninitialized value \\$x::y'),
    c('T199-quote', 'TRAPS; PLAN 11a', r'''my $x = 3; my @a = (1, 2); say "$x's"; say "$x:"; say "$x\::y"; say "${x}::y"; say "@a's"; say "$a[0]::x"; say "@a[0,1]::";''', out="3's\n3:\n3::y\n3::y\n1 2's\n1::x\n1 2::\n"),
    c('T200', 'TRAPS; PLAN 11a', 'my $b = 7; my $x = 3; say "a $ b"; say "$ x"; say "$\nx"; say "${ x }"; say "a ${\nx} b"; say "$ {x}";', out='a 7\n3\n3\n3\na 3 b\n3\n'),
    c('T200-at', 'TRAPS; PLAN 11a', r'''say "a @ b"; say "@"; say "a@"; say "@ x"; say "@@"; say "a@.b";''', out='a @ b\n@\na@\n@ x\n@@\na@.b\n'),
    c('T200-final', 'TRAPS; PLAN 11a', r'''say "cost $";''', compiles=False, err='Final \\$ should be'),
    c('T201', 'TRAPS; PLAN 11a', r'''my $x = 3; my @x = (7, 8, 9); say "$x[1]"; say "${x}[1]"; say "$x\[1]"; say "$x [1]"; say "@{x}[0,1]"; say "@x [0]"; say "$#{x}[0]";''', out='8\n3[1]\n3[1]\n3 [1]\n7 8 9[0,1]\n7 8 9 [0]\n2[0]\n'),
    c('T201-none', 'TRAPS; PLAN 11a', r'''my $x = 3; say "$x[1]";''', compiles=False, err='Global symbol "@x"'),
    c('T201-brace', 'TRAPS; PLAN 11a', r'''my @x = (7, 8, 9); say "${x[1]}"; say "@{x[0,1]}";''', out='8\n7 8\n', err='Ambiguous use of \\$\\{x\\[\\.\\.\\.\\]\\} resolved to \\$x\\[\\.\\.\\.\\]'),
    c('T202', 'TRAPS; PLAN 11a', r'''my @x = (7, 8, 9); my $i = 1; say "$x[01]"; say "$x[1.9]"; say "$x[1e0]"; say "$x[0x1]"; say "$x[ 1 ]"; say "$x[$i+1]"; say "$x[$i -1]"; say "$x[-$i]"; say "$x[$#x]"; say "$x[\"0\"]"; say "$x['1']"; say "$x[99999999999999999999]";''', out='8\n8\n8\n8\n8\n9\n7\n9\n9\n7\n8\n9\n'),
    c('T202-lines', 'TRAPS; PLAN 11a', 'my @x = (7, 8, 9); say "$x[\n1]"; say "$x[1 # c\n]"; say "@x[0,\n1]";', out='8\n8\n7 8\n'),
    c('T202-warns', 'TRAPS; PLAN 11a', r'''my @x = (7, 8, 9); say "$x[1,2]";''', out='9\n', err='Multidimensional syntax \\$x\\[1,2\\] not supported'),
    c('T202-under', 'TRAPS; PLAN 11a', r'''my @x = (7, 8, 9); say "$x[1_0]|";''', out='|\n', err='Use of uninitialized value \\$x\\[10\\]'),
    c('T202-quote', 'TRAPS; PLAN 11a', r'''my @x = (7, 8, 9); say "$x["0"]";''', compiles=False, err='Missing right curly or square bracket'),
    c('T203', 'TRAPS; PLAN 11a', r'''my $x = 3; my $y = 4; my @a = (1, 2); say "$x->"; say "$x->y"; say "$x->(1)"; say "$x->%*"; say "$x->$y"; say "$a[0]->"; say "@a[0,1]->"; say "$#a->"; say "${x}->[0]"; say "@{a}->[0]"; say "${x}{a}";''', out='3->\n3->y\n3->(1)\n3->%*\n3->4\n1->\n1 2->\n1->\n3->[0]\n1 2->[0]\n3{a}\n'),
    c('T203-arrow', 'TRAPS; PLAN 11a', r'''my $x = 3; say "$x->[0]";''', out='', exit=255, err='as an ARRAY ref'),
    c('T203-postfix', 'TRAPS; PLAN 11a', r'''my $x = 3; say "$x->@*";''', out='', exit=255, err='as an ARRAY ref'),
    c('T203-scalar', 'TRAPS; PLAN 11a', r'''my $x = 3; say "$x->$*";''', out='', exit=255, err='as a SCALAR ref'),
    c('T203-element', 'TRAPS; PLAN 11a', r'''my @a = (1, 2); say "$a[0][0]";''', out='', exit=255, err='as an ARRAY ref'),
    c('T203-array', 'TRAPS; PLAN 11a', r'''my @a = (1, 2); say "@a->[0]";''', out='', exit=255, err="Can't use an array as a reference"),
    c('T203-hash', 'TRAPS; PLAN 11a', r'''my $x = 3; say "$x{a}";''', compiles=False, err='Global symbol "%x"'),
    c('T203-slice', 'TRAPS; PLAN 11a', r'''my @a = (1, 2); say "@a[0,1][0]";''', compiles=False, err='syntax error'),
    c('T203-last', 'TRAPS; PLAN 11a', r'''my @a = (1, 2); say "$#a[0]";''', compiles=False, err='syntax error'),
    c('T204', 'TRAPS; PLAN 11a', r'''say "[@-]"; say "[@+]"; say "[@_]"; say "[@$]"; say "[@1]"; say "$(" eq $( ? "gid" : "no"; say "a$-b"; say "|$|"; say "$$" eq $$ ? "pid" : "no";''', out='[]\n[]\n[]\n[]\n[]\ngid\na0b\n|0\npid\n'),
    c('T204-email', 'TRAPS; PLAN 11a', r'''say "user@example.com";''', compiles=False, err='Possible unintended interpolation of @example'),
    c('T204-declared', 'TRAPS; PLAN 11a', r'''my @example = (1, 2); say "user@example.com"; say "100%"; my %h = (a => 1); say "%h"; sub f() { return 1 } say "&f()";''', out='user1 2.com\n100%\n%h\n&f()\n'),
    c('T204-backslash', 'TRAPS; PLAN 11a', r'''my $x = 3; say "$\{x}|";''', out='|\n', err='Use of uninitialized value \\$\\\\\\{"x"\\}'),
    c('T205', 'TRAPS; PLAN 11a', 'use utf8;\nuse open ":std", ":encoding(UTF-8)";\nmy $x = "e"; say "$xé";', compiles=False, err='Global symbol "\\$xé"'),
    c('T205-digit', 'TRAPS; PLAN 11a', 'use utf8;\nuse open ":std", ":encoding(UTF-8)";\nmy $x = "e"; say "$x٣";', compiles=False, err='Global symbol'),
    c('T205-mark', 'TRAPS; PLAN 11a', 'use utf8;\nuse open ":std", ":encoding(UTF-8)";\nmy $x = "e"; say "$x́";', compiles=False, err='Global symbol'),
    c('T205-text', 'TRAPS; PLAN 11a', 'use utf8;\nuse open ":std", ":encoding(UTF-8)";\nmy $x = "e"; my @a = (1, 2); say "$x→"; say "$x—$x"; say "${x}é"; say "$x·"; say "$a[0]é";', out='e→\ne—e\neé\ne·\n1é\n'),
    c('T205-longest', 'TRAPS; PLAN 11a', r'''my $x = 3; say "$x_";''', compiles=False, err='Global symbol "\\$x_"'),
    c('T206', 'TRAPS; PLAN 11a', r'''my @a = (1, 2, 3); my $i = 0; say "@a[0]"; say "@a[$i]";''', out='1\n1\n', err='(?s)Scalar value @a\\[0\\] better written as \\$a\\[0\\].*Scalar value @a\\[\\.\\.\\.\\] better written'),
    c('T206-quiet', 'TRAPS; PLAN 11a', r'''my @a = (1, 2, 3); my $i = 1; my @w = (0, 2); say "@a[0, 1]"; say "@a[0 .. 1]"; say "@a[$i .. 2]"; say "@a[1,]"; say "@a[2 .. 0]|"; say "@a[-1, 0]"; say "@a[@w]"; say "@a[0 .. 1, 2]"; say "@a[1..1]";''', out='1 2\n1 2\n2 3\n2\n|\n3 1\n1 3\n1 2 3\n2\n'),
    c('T207', 'TRAPS; PLAN 11a', r'''my $t = true; my $f = false; say "[$t][$f]"; my $s = "$f"; say $s + 1;''', out='[1][]\n1\n', err='Argument "" isn.t numeric in addition'),
    c('T207-numbers', 'TRAPS; PLAN 11a', r'''my $n = 1e15; say "$n"; $n = 3.0; say "$n"; $n = 0.1 + 0.2; say "$n"; my @a = (0.1, 1e21, -0.0, 1/3, true); say "@a"; my $x = 5; say "$x" + "$x"; say "0$x" + 1; say "$x.$x" + 1;''', out='1e+15\n3\n0.3\n0.1 1e+21 0 0.333333333333333 1\n10\n6\n6.5\n'),
    c('T208', 'TRAPS; PLAN 11a', r'''my $u; say "a${u}b";''', out='ab\n', err='Use of uninitialized value \\$u in concatenation'),
    c('T208-array', 'TRAPS; PLAN 11a', r'''my @a = (1, undef, 2); say "@a";''', out='1  2\n', err='Use of uninitialized value \\$a\\[1\\] in join or string'),
    c('T208-element', 'TRAPS; PLAN 11a', r'''my @a = (1, 2); say "$a[9]|"; say scalar(@a);''', out='|\n2\n', err='Use of uninitialized value \\$a\\[9\\]'),
    c('T208-slice', 'TRAPS; PLAN 11a', r'''my @a = (1, 2); say "@a[5,6]|"; say scalar(@a);''', out=' |\n2\n', err='Use of uninitialized value in join or string'),
    c('T208-empty', 'TRAPS; PLAN 11a', r'''my @a = (); say "[@a]"; my @b = (1, 2); my @c = (3); say "@b@c"; say "@b" eq join(" ", @b) ? "same" : "differ";''', out='[]\n1 23\nsame\n'),
    c('T209', 'TRAPS; PLAN 11a', r'''my $x = 3; for my $v ("$x", "$x-") { $x = 5; say $v; } my @a = (1, 2); for my $v ("@a") { push @a, 3; say $v; } for my $v ("$a[0]") { $a[0] = 9; say $v; } my @b = map { "$_" } @a; $b[0] = 0; say "@a";''', out='3\n3-\n1 2\n1\n9 2 3\n'),
    c('T210', 'TRAPS; PLAN 11a', r'''my @a = (3, 1, 2); my @b = sort { say "$a[0]$b"; $a <=> $b } @a; say "$_:" for @b; my @c = map { "a$_" } @a; say "@c"; my @d = map { "$_" x 2 } @a; say "@d";''', out='31\n32\n33\n1:\n2:\n3:\na3 a1 a2\n33 11 22\n'),
    c('T210-underscore', 'TRAPS; PLAN 11a', r'''my @a = (3); for (@a) { say "$_[0]|"; }''', out='|\n', err='Use of uninitialized value \\$_\\[0\\]'),
    c('T210-hash', 'TRAPS; PLAN 11a', r'''my @a = (1, 2); my @b = map { "$_", 1 } @a;''', compiles=False, err='syntax error'),
    c('T210-brace', 'TRAPS; PLAN 11a', r'''my $s = 1; my $q = 2; my $y = 3; my $m = 4; my $tr = 5; my $print = 6; my @sort = (7, 8); say "${s}${q}${y}${m}${tr}${print}@{sort}";''', out='1234567 8\n'),
    # ---- step 11a: found by its review
    c('T211', 'TRAPS; PLAN 11a', r"""my @a = (0 .. 20); say "$a[010]"; say "$a[-010]"; say "@a[010, 011]"; say "@a[07 .. 010]";""", out='8\n13\n8 9\n7 8\n'),
    c('T211-eight', 'TRAPS; PLAN 11a', r"""my @a = (0 .. 20); say "$a[08]";""", compiles=False, err='Illegal octal digit .8.'),
    c('T211-large', 'TRAPS; PLAN 11a', r"""my @a = (0 .. 20); say "$a[18446744073709551615]"; say "$a[18446744073709551614]";""", out='20\n19\n'),
    c('T211-edge', 'TRAPS; PLAN 11a', r"""my @a = (0 .. 20); say "$a[9223372036854775807]|";""", out='|\n', err='Use of uninitialized value'),
    c('T212', 'TRAPS; PLAN 11a', r"""my $t = "t"; my $u = "u"; my $x = "a"; my $z = "z"; $t .= ($u = "$x$z$x"); say "$t $u"; $t = "t"; $t .= ($u = (1 ? "$x$z" : 0)); say "$t $u"; $x = 3; say "$x" -1; my @a = (1, 2); sub f() { return "@a" } my $v = f(); say $v;""", out='taza u\ntaz u\n2\n1 2\n'),
    # ---- found by the census's first run, before step 11b was proposed
    c('T213', 'TRAPS', r"""my @a = (1); my $n = ($a[0] = 5) + ($a[0] = 7); say $n; @a = (1); $n = ++$a[0] + ++$a[0]; say $n; @a = (1); $n = (++$a[0]) + $a[0]++; say $n; @a = (1, 2, 3); $n = ($a[0] += 1) + ($a[0] += 1); say $n; @a = (1); my @l = ($a[0] = 5, $a[0] = 7); say "@l"; @a = (1); my $v = (($a[0] = 5), ($a[0] = 7))[0]; say $v;""", out='14\n6\n5\n6\n7 7\n7\n'),
    c('T213-sub', 'TRAPS', r"""my @a = (1); sub nine() { $a[0] = 9; return 1; } my $n = ($a[0] = 5) + nine(); say $n;""", out='10\n'),
    # ---- step 12, hashes: found proposing it
    c('T214', 'TRAPS; PLAN 12', r"""my %h = (true => 1, undef => 2, print => 3, q => 4, x => 5, if => 6, and => 7, v65 => 8); say join ",", sort keys %h; sub f() { return "ff" } my %g = (f() => 1, f => 2); say join ",", sort keys %g; my %n = (1 => "a", 1.0 => "b", "1" => "c", 1e3 => "d", 0.5 => "e"); say join ",", map { "$_=$n{$_}" } sort keys %n;""", out='and,if,print,q,true,undef,v65,x\nf,ff\n0.5=e,1=c,1000=d\n'),
    c('T214-lines', 'TRAPS; PLAN 12', 'my %h = (a\n=> 1, b # c\n => 2); say join ",", sort keys %h;', out='a,b\n'),
    c('T214-octal', 'TRAPS; PLAN 12', r"""my %h = (010 => "a", 0x10 => "c", 01 => "d"); say join ",", sort keys %h; say $h{8}; say $h{010};""", out='1,16,8\na\na\n'),
    c('T214-package', 'TRAPS; PLAN 12', r"""my %h = (a::b => 1);""", compiles=False, err='Bareword "a::b" not allowed'),
    c('T214-minus', 'TRAPS; PLAN 12', r"""my %h = (-a => 1); say keys %h; my %g; $g{-b} = 1; say keys %g;""", out='-a\n-b\n'),
    c('T215', 'TRAPS; PLAN 12', r"""my %h; $h{q} = 1; $h{s} = 2; $h{y} = 3; $h{x} = 4; $h{if} = 5; $h{time} = 6; $h{shift} = 7; $h{true} = 8; $h{undef} = 9; $h{(true)} = 10; $h{v65} = 11; say join ",", sort keys %h;""", out='1,if,q,s,shift,time,true,undef,v65,x,y\n'),
    c('T215-plus', 'TRAPS; PLAN 12', r"""my %h; $h{+b} = 2;""", compiles=False, err='Bareword "b" not allowed'),
    c('T215-number', 'TRAPS; PLAN 12', r"""my %h = (1 => "x", 8 => "y"); say $h{1.0}, $h{01}, $h{1e0}, $h{0+1}, $h{010}, $h{0x8}, $h{4*2}; my %k; $k{1e15} = 1; $k{0.1+0.2} = 2; $k{-0.0} = 3; my $t = true; my $f = false; $k{$t} = 4; $k{$f} = 5; say join ",", map { "[$_]" } sort keys %k;""", out='xxxxyyy\n[],[0],[0.3],[1],[1e+15]\n'),
    c('T215-undef', 'TRAPS; PLAN 12', r"""my %h; my $u; $h{$u} = 1; say scalar(keys %h);""", out='1\n', err='Use of uninitialized value \\$u in hash element'),
    c('T216', 'TRAPS; PLAN 12', r"""my %h = (a => 1); my $v = $h{b}; my $x = $h{c} // 5; my $y = defined $h{d}; my @l = ($h{e}, 1); sub one($p) { return 1 } one($h{f}); say scalar(keys %h); $h{g} &&= 7; say exists $h{g} ? "made" : "not";""", out='1\nmade\n'),
    c('T216-made', 'TRAPS; PLAN 12', r"""my %h = (a => 1); for my $v ($h{p}) { } my @r = map { 1 } $h{q}; @r = sort { 0 } $h{r}, $h{s}; sub all(@x) { return 1 } all(@h{"t", "u"}); for my $v (@h{"v", "w"}) { } say join ",", sort keys %h;""", out='a,p,q,r,s,t,u,v,w\n'),
    c('T217', 'TRAPS; PLAN 12', r"""my %h = (a => 1); for my $v (values %h) { $h{a} = 9; say $v; } %h = (a => 1); for my $v (%h) { $h{a} = 9; say $v; } %h = (a => 1); for my $v ($h{a}) { $h{a} = 9; say $v; } %h = (a => 1); my @r = map { $h{a} = 9; $_ } values %h; say "@r"; %h = (a => 1); for my $k (keys %h) { $h{$k} = 9; $h{z} = 1; say $k; } say scalar(keys %h);""", out='9\na\n9\n9\n9\na\n2\n'),
    c('T218', 'TRAPS; PLAN 12', r"""my %c = (n => 0); sub inc() { $c{n}++; return $c{n} } say join ",", $c{n}, inc(), $c{n}; %c = (n => 0); say $c{n} + inc(); %c = (n => 1); sub chg() { $c{n} = 2; return 9 } my @l = (values(%c), chg()); say "@l"; %c = (n => 1); sub add() { $c{m} = 2; return 9 } @l = (keys(%c), add()); say scalar(@l); %c = (n => 1); my $s = ($c{n} = 5) + ($c{n} = 7); say $s;""", out='1,1,1\n2\n2 9\n2\n14\n'),
    c('T218-order', 'TRAPS; PLAN 12', r"""my %h; my $i = "a"; $h{$i} = ($i = "b"); say join ",", sort keys %h; %h = (); $i = "a"; $h{$i} .= ($i = "b"); say join ",", map { "$_=$h{$_}" } sort keys %h;""", out='b\na=b\n'),
    c('T219', 'TRAPS; PLAN 12', r"""my %h = (a => 1, b => 2); say scalar(%h); my $n = %h; say $n; say %h ? "t" : "f"; my %e; say %e ? "t" : "f"; say %h + 0; say "n" . %h; $n = keys %h; say $n; my @l = %h; say scalar(@l); my @y = (%h) x 2; say scalar(@y);""", out='2\n2\nt\nf\n2\nn2\n2\n4\n8\n'),
    c('T219-odd', 'TRAPS; PLAN 12', r"""my %h = (a => 1, "b"); say scalar(keys %h);""", out='2\n', err='Odd number of elements in hash assignment'),
    c('T219-odd-argument', 'TRAPS; PLAN 12', r"""sub f(%o) { return scalar(keys %o) } say f(a => 1, "b");""", out='', exit=255, err='Odd name/value argument for subroutine'),
    c('T219-twice', 'TRAPS; PLAN 12', r"""my %h = (a => 1, a => 2); say $h{a}, scalar(keys %h); sub f(%o) { return join ",", map { "$_=$o{$_}" } sort keys %o } say f(a => 1, b => 2); my %g = (c => 3); say f(%g, d => 4); sub g($x, %o) { return $x . scalar(keys %o) } say g(1), g(1, a => 2);""", out='21\na=1,b=2\nc=3,d=4\n1011\n'),
    c('T220', 'TRAPS; PLAN 12', r"""my %h = (a => 1); say exists $h{a} + 1;""", out='', exit=255, err='exists argument is not a HASH or ARRAY element'),
    c('T220-delete', 'TRAPS; PLAN 12', r"""my %h = (a => 1); say delete $h{a} + 1;""", out='', exit=255, err='delete argument is not a HASH or ARRAY element or slice'),
    c('T220-fine', 'TRAPS; PLAN 12', r"""my %h = (a => 1, b => 2, c => 3); say exists($h{a}) + 1; say "yes" if exists $h{a} and not exists $h{z}; my $n = delete($h{a}) + 1; say $n; my $e = delete $h{zz}; say defined($e) ? "def" : "undef"; my @d = delete @h{"b", "c"}; say "@d"; say scalar(keys %h); my %u = (a => undef); say exists $u{a} ? 1 : 0, defined $u{a} ? 1 : 0;""", out='2\nyes\n2\nundef\n2 3\n0\n10\n'),
    c('T221', 'TRAPS; PLAN 12', r"""my %h = (a => 1, "a b" => 2, 1 => "x"); my $k = "a"; say "v=$h{a} $h{$k} $h{'a b'} $h{1} $h{01} $h{ a }|$h{a}->|$h{a}::x|$h{a}s|%h";""", out='v=1 1 2 x x 1|1->|1::x|1s|%h\n'),
    c('T221-quote', 'TRAPS; PLAN 12', r"""my %h = (a => 1); say "v=$h{"a"}";""", compiles=False, err='Missing right curly or square bracket'),
    c('T221-slice', 'TRAPS; PLAN 12', r"""my %h = (a => 1, b => 2); say "@h{'a','b'}"; say "@h{a}";""", out='1 2\n1\n', err='Scalar value @h\\{"a"\\} better written as \\$h\\{"a"\\}'),
    c('T221-nested', 'TRAPS; PLAN 12', r"""my %h = (a => 1); say "$h{a}{b}";""", out='', exit=255, err='as a HASH ref'),
    c('T222', 'TRAPS; PLAN 12', r"""my %h = (b => 2, a => 1, c => 3); my @k = keys %h; my @v = values %h; my @p = %h; say $h{$k[0]} == $v[0] && $h{$k[2]} == $v[2] && $p[0] eq $k[0] && $p[1] == $v[0] ? "one order" : "not"; delete $h{a}; $h{a} = 3; say scalar(keys %h); my %g = %h; $g{a} = 9; say $h{a};""", out='one order\n3\n3\n'),
    # ---- step 12: found by its review
    c('T223', 'TRAPS; PLAN 12', 'my %h; $h{\n    true\n} = "a"; $h{ true } = "b"; $h{false   # the flag\n} = "c"; $h{\n    v65 } = "d"; $h{ v65 } = "e"; say join ",", map { "[$_]=$h{$_}" } sort keys %h;', out='[]=c,[1]=a,[A]=d,[true]=b,[v65]=e\n'),
    c('T223-word', 'TRAPS; PLAN 12', 'my %h; $h{\n    name\n} = 1;', compiles=False, err='Bareword "name" not allowed'),
    c('T224', 'TRAPS; PLAN 12', 'my %h = (v65 => 1, v66\n    => 2, v67   # c\n    => 3, name\n    => 4); say join ",", sort keys %h;', out='B,C,name,v65\n'),
    c('T225', 'TRAPS; PLAN 12', r"""my %h = (a => 1); say keys %h + 1;""", compiles=False, err='Type of arg 1 to keys must be hash or array'),
    c('T225-values', 'TRAPS; PLAN 12', r"""my %h = (a => 1); say values %h . "x";""", compiles=False, err='Type of arg 1 to values must be hash or array'),
    c('T225-fine', 'TRAPS; PLAN 12', r"""my %h = (a => 1); say keys(%h) + 1; say "two" if keys %h == 1 or values %h > 5;""", out='2\ntwo\n'),
    c('T226', 'TRAPS; PLAN 12', r"""sub f($x, %) { return "ok $x" } say f(1, 2, 3); say f(1, 2);""", out='ok 1\n', exit=255, err='Odd name/value argument for subroutine'),
    c('T226-entry', 'TRAPS; PLAN 12', r"""sub t() { say "default"; return 1 } sub f($x //= t(), %o) { return 1 } say "before"; f(undef, "k");""", out='before\n', exit=255, err='Odd name/value argument for subroutine'),
    c('T227', 'TRAPS; PLAN 12', r"""my %h = (a => 1); my @r = (0, 0, 0); @r = ("$h{a}->", "$h{a}->%*", "$h{a}::x", "$h{a}(1)"); say "@r";""", out='1-> 1->%* 1::x 1(1)\n'),
    c('T227-index', 'TRAPS; PLAN 12', r"""my %h = (a => 1); say "$h{a}[0]";""", out='', exit=255, err='as an ARRAY ref'),
    c('T227-arrow', 'TRAPS; PLAN 12', r"""my %h = (a => 1); say "$h{a}->{b}";""", out='', exit=255, err='as a HASH ref'),
    c('T228', 'TRAPS; PLAN 12', r"""my %h; @h{"a", "b"} = (1); say exists $h{b} ? "made" : "not"; my @a = (9); @a[1, 2] = (5); say scalar(@a); my @b; @b[2, 1] = (); say scalar(@b); my (%g, $x) = (p => 1, q => 2); say join(",", sort keys %g), defined $x ? "set" : "undef";""", out='made\n3\n3\np,qundef\n'),
    c('T229', 'TRAPS; PLAN 12', r"""my %h = (a => 1, b => 2); sub n() { return %h } my $c = n(); say $c;""", out='2\n'),
    c('T230', 'TRAPS', r"""my @a; my $i = 0; $a[$i = 2] = $i . "v"; say $a[2]; $i = 0; $a[$i = 2] = "$i$i"; say $a[2]; $i = 0; $a[$i = 2] = 0 || $i . "v"; say $a[2]; sub bump() { $i = 2; return 2 } $i = 0; $a[bump()] = $i . "v"; say $a[2]; my %h; $i = "a"; $h{$i = "k"} = $i . "v"; say %h;""", out='2v\n22\n2v\n2v\nkkv\n'),
    c('T230-early', 'TRAPS', r"""my @a; my $i = 0; $a[$i = 2] = $i x 1; say $a[2]; $i = 0; $a[$i = 2] = uc($i . "v"); say $a[2]; $i = 0; $a[$i = 2] = "$i"; say $a[2]; $i = 0; ($a[$i = 2]) = ($i . "v"); say $a[2];""", out='0\n0V\n0\n0v\n'),
    # ---- found proposing step 13
    c('T231', 'TRAPS; PLAN 13', r"""my $r; my $x = $r->{a}; say ref($r); my $s; my $y = $s->[0]; say ref($s); my $t; say exists $t->{a} ? "y" : "n", ref($t); my $u; delete $u->{a}; say ref($u); my $v; say $v->$#*, ref($v);""", out='HASH\nARRAY\nnHASH\nHASH\n-1ARRAY\n'),
    c('T232-dies', 'TRAPS; PLAN 13', r"""my $r; my @x = $r->@*; say "not reached";""", out='', exit=255, err='undefined value as an ARRAY reference'),
    c('T232-dies-count', 'TRAPS; PLAN 13', r"""my $r; my $n = scalar($r->@*); say "not reached";""", out='', exit=255, err='undefined value as an ARRAY reference'),
    c('T232-dies-sort', 'TRAPS; PLAN 13', r"""my $r; my @k = sort $r->@*; say "not reached";""", out='', exit=255, err='undefined value as an ARRAY reference'),
    c('T232-dies-join', 'TRAPS; PLAN 13', r"""my $r; my $j = join(",", $r->@*); say "not reached";""", out='', exit=255, err='undefined value as an ARRAY reference'),
    c('T232-dies-hash', 'TRAPS; PLAN 13', r"""my $r; if ($r->%*) { } say "not reached";""", out='', exit=255, err='undefined value as a HASH reference'),
    c('T232-dies-scalar', 'TRAPS; PLAN 13', r"""my $r; my $x = $$r; say "not reached";""", out='', exit=255, err='undefined value as a SCALAR reference'),
    c('T232-made', 'TRAPS; PLAN 13', r"""sub n(@a) { return scalar(@a) } my $r; for my $x ($r->@*) { } say ref($r); my $s; my @k = keys $s->%*; say ref($s); my $t; my @m = map { $_ } $t->@*; say ref($t); my $u; my @g = grep { $_ } $u->@*; say ref($u); my $v; say n($v->@*), ref($v); my $w; my @s = $w->@[0, 1]; say ref($w); my $p; my $q = pop @$p; say ref($p); my $o; my @vs = values $o->%*; say ref($o);""", out='ARRAY\nHASH\nARRAY\nARRAY\n0ARRAY\nARRAY\nARRAY\nHASH\n'),
    c('T233', 'TRAPS; PLAN 13', r"""my %h; say exists $h{a}{b} ? "y" : "n", exists $h{a} ? "made" : "no"; my %g; my $d = defined $g{a}{b}; say exists $g{a} ? "made" : "no"; my %f; my $x = $f{a}{b}{c}; say join(",", sort keys %f), ref($f{a}{b}); my %e; $e{y}{z} &&= 4; say exists $e{y} ? "made" : "no", exists $e{y}{z} ? "made" : "no"; my %d; if ($d{a} && $d{a}{b}) { } say exists $d{a} ? "made" : "no"; my @a; my $t = $a[3]{k}; say scalar(@a);""", out='nmade\nmade\naHASH\nmademade\nno\n4\n'),
    c('T234-string', 'TRAPS; PLAN 13', r"""my $x = 5; my $y = $x->[0]; say "not reached";""", out='', exit=255, err='as an ARRAY ref while \"strict refs\"'),
    c('T234-kind', 'TRAPS; PLAN 13', r"""my $x = [1]; my $y = $x->{k}; say "not reached";""", out='', exit=255, err='Not a HASH reference'),
    c('T234-empty', 'TRAPS; PLAN 13', r"""my $x = ""; $x->{a} = 1; say "not reached";""", out='', exit=255, err='as a HASH ref while \"strict refs\"'),
    c('T234-false', 'TRAPS; PLAN 13', r"""my $x = false; $x->[0] = 1; say "not reached";""", out='', exit=255, err='as an ARRAY ref while \"strict refs\"'),
    c('T235', 'TRAPS; PLAN 13', r"""my @a = (1, 2); my $r = \@a; say $a[0], ($r->[0] = 5); my $s = [1, 2]; sub f($q) { $q->[0] = 9; return "x" } say $s->[0], f($s); my $t = [1, 2]; say $t->[0] . f($t); my $u = [1, 2]; sub g($q) { $q->[0] = 9; return 1 } say $u->[0] + g($u); my $x = 1; my $p = \$x; say $x, ($$p = 5); my $y = 1; my $o = \$y; sub h($q) { $$q = 9; return 1 } say $y . h($o);""", out='55\n9x\n9x\n10\n55\n91\n'),
    c('T235-string', 'TRAPS; PLAN 13', r"""my $r = {a => 1}; sub f($q) { $q->{a} = 9; return "x" } my $s = "$r->{a}" . f($r); say $s; my $t = [1, 2]; sub g($q) { push $q->@*, 3; return 1 } my @b = ($t->@*, g($t)); say "@b";""", out='1x\n1 2 1\n'),
